// ── Fibonacci: three implementations ──────────────────────────

// 1. Naive recursion — O(2^n) time, O(n) stack
function fibNaive(n) {
  if (n <= 1) return n;
  return fibNaive(n - 1) + fibNaive(n - 2);
}

// 2. Memoisation (top-down DP) — O(n) time, O(n) space
function fibMemo(n, memo = new Map()) {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n);
  const result = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, result);
  return result;
}

// 3. Tabulation (bottom-up DP) — O(n) time, O(1) space with rolling vars
function fibTab(n) {
  if (n <= 1) return n;
  let prev = 0, curr = 1;
  for (let i = 2; i <= n; i++) {
    [prev, curr] = [curr, prev + curr];
  }
  return curr;
}

// ── Coin change — minimum coins to make amount W ───────────────
// dp[w] = min coins to make amount w
function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0; // base case: 0 coins to make amount 0

  for (let w = 1; w <= amount; w++) {
    for (const coin of coins) {
      if (coin <= w && dp[w - coin] + 1 < dp[w]) {
        dp[w] = dp[w - coin] + 1;
      }
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount];
}

console.log(fibNaive(10));  // 55  (slow for large n)
console.log(fibMemo(50));   // 12586269025
console.log(fibTab(50));    // 12586269025

console.log(coinChange([1, 5, 10, 25], 36)); // 3  (25 + 10 + 1)
console.log(coinChange([2], 3));             // -1 (impossible)

// ── 0/1 Knapsack — maximum value within weight capacity ────────
// Each item can be taken at most once (0 or 1).
// dp[i][w] = max value using first i items with capacity w
//
// Recurrence:
//   dp[i][w] = dp[i-1][w]                           if item i doesn't fit
//   dp[i][w] = max(dp[i-1][w],
//                  dp[i-1][w - weight[i]] + value[i]) if item i fits

function knapsack01(weights, values, capacity) {
  const n = weights.length;
  // Space-optimised: 1D array updated in-place (iterate w right-to-left)
  const dp = new Array(capacity + 1).fill(0);

  for (let i = 0; i < n; i++) {
    // Right-to-left prevents using item i more than once
    for (let w = capacity; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
    }
  }
  return dp[capacity];
}

console.log(knapsack01([2, 3, 4, 5], [3, 4, 5, 6], 5)); // 7  (items 0+1: weight 5, value 7)

// ── DP problem identification checklist ────────────────────────
//
// Ask yourself:
// 1. Can the problem be broken into smaller subproblems?     → recursion candidate
// 2. Are subproblems reused (overlapping)?                    → add memoisation
// 3. Does the optimal whole use optimal parts?                → optimal substructure
// 4. Can I define dp[state] clearly and write a recurrence?  → tabulate
//
// Common DP state dimensions:
//   1D:  dp[i]     — position/amount (Fibonacci, coin change)
//   2D:  dp[i][j]  — two sequences or item+capacity (LCS, knapsack)
//   2D:  dp[i][j]  — substring range (palindrome, matrix chain)
